/**
 * dsh-notifier stores 域 —— 通知历史实现（jsonl）：写队列串行化 + 原子写 + 滚动上限与按时效过滤。
 *
 * 保留天数每次读时现取：装配期取快照会在用户改设置后失效。
 */
import { readFile } from "node:fs/promises";
import {
  writeTextAtomic,
  HISTORY_FILE_NAME,
  normalizeReason,
  normalizeSoundWarning,
  notifierFile,
} from "../../../shared/interface.ts";
import type {
  ChannelDelivery,
  ClearOutcome,
  HistoryDeps,
  HistoryEntry,
  ParsedHistoryLine,
} from "./type.ts";

/** 通知历史滚动上限（行数；超出后从尾部截断重写）。 */
const HISTORY_LIMIT = 200;

/** 一天的毫秒数：按天清理与按天过滤是同一个刻度。 */
const DAY_MS = 86_400_000;

/** 队列的尾哨：只用来把「已消费掉的失败」变成一次正常的落定，不做任何事。 */
const NOOP = (): void => {};

/** 未装配时的占位：装配是必经路径，能力写成抛错，真被读到应当场暴露而不是静默按默认设置清理。 */
const UNINSTALLED: HistoryDeps = {
  logger: { warn: () => {} },
  config: {
    readConfig: () => {
      throw new Error("dsh-notifier: 历史存储尚未装配");
    },
  },
};

/** 通知历史：jsonl 追加写，读时滚动截断与按天过滤。 */
class HistoryStore {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 落盘路径：DSH home 由环境决定、进程内不变，故随实例一次性定下。 */
  private readonly file = notifierFile(HISTORY_FILE_NAME);
  /** 装配入参（失败出口）。 */
  private deps: HistoryDeps = UNINSTALLED;
  /** 写队列串行化：并发「读-改-写」会互相覆盖丢记录。 */
  private queue: Promise<void> = Promise.resolve();

  /** 装配：单次生效。 */
  install(deps: HistoryDeps): void {
    if (this.installed) throw new Error("dsh-notifier: 历史存储只能装配一次");
    this.installed = true;
    this.deps = deps;
  }

  /** 卸载：放开装配入参。在飞的写入不等待——它们各有自己的失败出口。 */
  release(): void {
    this.installed = false;
    this.deps = UNINSTALLED;
  }

  /**
   * 追加一条记录：入队即返回（不阻塞通知主流程），失败仅经日志出口告警。
   *
   * 经 `enqueue` 而不是直接 `this.queue = this.queue.then(...)`：直接赋值时排在本条之后的那次
   * 写会挂在一个可能被拒绝的 promise 上，一次失败就让此后每一条历史静默不写。与 clear 共用
   * 入队口，这条护栏就不必在两条写上各记得一次。
   */
  append(entry: HistoryEntry): void {
    // 装配入参在调用点取一次：写发生在稍后，卸载会把 deps 换回占位，取晚一步就连失败日志都落不下来。
    const deps = this.deps;
    void this.enqueue(async () => {
      try {
        const lines = await this.currentLines();
        lines.push(JSON.stringify(entry));
        // 写入是唯一能减少行数的时机，读侧的过滤只是兜底。
        const keepDays = deps.config.readConfig().historyMaxAgeDays;
        const kept =
          keepDays > 0
            ? lines.filter((line) => withinRetention(line, entry.ts - keepDays * DAY_MS))
            : lines;
        const trimmed = kept.length > HISTORY_LIMIT * 2 ? kept.slice(-HISTORY_LIMIT) : kept;
        const written = await writeTextAtomic(this.file, `${trimmed.join("\n")}\n`);
        if (!written.ok) {
          deps.logger.warn(`dsh-notifier: 历史记录写入失败: ${written.reason}`);
        }
      } catch (cause) {
        deps.logger.warn(
          `dsh-notifier: 历史记录写入失败: ${cause instanceof Error ? cause.message : String(cause)}`,
        );
      }
    });
  }

  /** 最近记录（尾部最多 `HISTORY_LIMIT` 条；保留期 > 0 时先按天过滤）。 */
  async read(): Promise<HistoryEntry[]> {
    let text: string;
    try {
      text = await readFile(this.file, "utf8");
    } catch {
      // 没有历史文件与历史为空是同一件事：都回答「没有记录」，不是错误。
      return [];
    }
    const keepDays = this.deps.config.readConfig().historyMaxAgeDays;
    // 截止点用「现在」：调小保留天数后应立刻看不到旧记录，不必等下一次写入顺手清理。
    const cutoff = keepDays > 0 ? Date.now() - keepDays * DAY_MS : 0;
    const records: HistoryEntry[] = [];
    for (const line of text
      .split("\n")
      .filter(Boolean)
      .slice(-HISTORY_LIMIT * 2)) {
      const parsed = parseLine(line);
      if (!parsed.ok) continue;
      if (cutoff > 0 && typeof parsed.entry.ts === "number" && parsed.entry.ts < cutoff) continue;
      records.push(parsed.entry);
    }
    // 上限是读语义：手改文件绕过写侧时，读面仍只交出最近 HISTORY_LIMIT 条。
    records.splice(0, Math.max(0, records.length - HISTORY_LIMIT));
    return records;
  }

  /**
   * 清空全部记录。**进写队列**（#1016 残留 1）。
   *
   * 为什么不进队列是一条真数据竞态，不只是顺序问题：清空在队列外时，一次在飞的 append 会
   * 「读旧行 → 追加新行 → 写回」，而清空恰好插在它读与写之间——清空把文件截空之后，那一次
   * append 用它读到的旧行把**整段旧记录原样写回**。用户看到「已清空 N 条」，刷新后记录全在。
   * 落进同一条队列后次序唯一：先到的 append 落完盘再清空，后到的 append 落在清空之后。
   *
   * 返回两态而不是条数：落盘失败必须让调用方**看得见**（返回裸条数时端点只能答 200，界面提示
   * 「已清空 N 条」而文件纹丝未动）。**本方法不抛错**——抛错经路由的失败出口转成 500，error
   * 字段是 Node 错误原文（带 errno 与绝对路径），与 issue #1016「errno/路径不外送」直接冲突。
   */
  async clear(): Promise<ClearOutcome> {
    // 装配入参在调用点取一次：写发生在稍后，卸载会把 deps 换回占位，取晚一步连告警都落不下来。
    const deps = this.deps;
    return this.enqueue(async () => {
      // 计条数与写入之间不再有并发写：整段在队列内，前面排队的写都已落盘。
      let removed = 0;
      try {
        removed = (await readFile(this.file, "utf8")).split("\n").filter(Boolean).length;
      } catch {
        // 文件不存在：没有记录可清，清空动作本身照做（把文件补出来）。
      }
      const written = await writeTextAtomic(this.file, "");
      if (!written.ok) {
        // 告警保留（诊断要），但**不再由它决定返回值**：日志是给人看的，返回值是给端点与界面的。
        deps.logger.warn(`dsh-notifier: 清空历史失败: ${written.reason}`);
        return { ok: false, reason: "unavailable" };
      }
      return { ok: true, removed };
    });
  }

  /**
   * 把一次写挂到队列尾。写法照抄 config 域的同名方法。
   *
   * 前两条是**同一道护栏的两个冗余机制**，各自都足以挡住「前一次抛错 ⇒ 此后每一条历史都静默不写」：
   * 1. `.then(task, task)`——两个分支都给同一个 task，前一次无论成败后一次都照常执行。
   * 2. `result.then(NOOP, NOOP)` 中和之后**赋回队列的才是它**，于是队列上永远不挂 rejected promise。
   *    append 的 task 自己 try/catch 住了；clear 的 task 若在兜底之外抛出（判据推翻了「绝不抛」的
   *    前提），接住那次抛出的是第 1 条——第 2 条在**当前这个双分支写法下并不是**「抛出后后续写被
   *    跳过」的原因，那个症状要退回单分支 `.then(task)` 才成立。
   *
   * **正因冗余，改掉任何一条单独看都判不出来**：实测单独去掉第 2 条全绿、单独退回单分支 `.then(task)`
   * 也全绿，**两条一起去掉**才红，且只红 `test/unit/stores/history.test.ts` 里「清空的 task 抛错后，
   * 紧随其后的 append 仍然落盘」那一条。这既是它们必须一起保留的理由（少一条时行为不变，但缓冲
   * 归零），也是那条判据只能断**性质**、断不了某一条写法的原因。
   *
   * 3. task 内**绝不再入队**：enqueue 同步把队列设成 `result.then(...)`，task 里再入队就是等自己
   *    刚挂上去的 tail，而那个 tail 排在自己后面，自己不返回它就不 resolve（死锁）。config 域为
   *    此把 apply 与 commit 之间的经队列路径在结构上写死，这里靠同一条纪律。
   */
  private enqueue<T>(task: () => Promise<T>): Promise<T> {
    const result = this.queue.then(task, task);
    this.queue = result.then(NOOP, NOOP);
    return result;
  }

  /** 现有行：读不到文件即空列表（首次写入从零开始，与读语义一致）。 */
  private async currentLines(): Promise<string[]> {
    try {
      return (await readFile(this.file, "utf8")).split("\n").filter(Boolean);
    } catch {
      return [];
    }
  }
}

/** 按天清理时一行的去留：坏行保守保留——「读不出来」不等于「过期」，删掉等于毁掉还有救的内容。 */
function withinRetention(line: string, cutoff: number): boolean {
  const parsed = parseLine(line);
  if (!parsed.ok) return true;
  return typeof parsed.entry.ts === "number" && parsed.entry.ts >= cutoff;
}

/** 解析一行 jsonl：只把 JSON 对象算作读到一行——非对象的合法 JSON 取字段会抛，当坏行处理。 */
function parseLine(line: string): ParsedHistoryLine {
  try {
    const parsed = JSON.parse(line) as unknown;
    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed))
      return { ok: false };
    return { ok: true, entry: normalizeEntry(parsed as HistoryEntry) };
  } catch {
    return { ok: false };
  }
}

/**
 * 归一化一条历史记录：只重写 `channels` 里的理由——升级前的行存的是散文，之后存结构化对象，
 * 客户端不该为「同一字段两种形态」各写一遍渲染。其余字段原样透传：历史是持久格式，可能躺着
 * 早已退役的种类，本域不认识不等于该丢。
 */
function normalizeEntry(entry: HistoryEntry): HistoryEntry {
  if (!Array.isArray(entry.channels)) return entry;
  const channels: ChannelDelivery[] = [];
  for (const delivery of entry.channels) {
    const normalized = normalizeDelivery(delivery);
    if (normalized !== undefined) channels.push(normalized);
  }
  return { ...entry, channels };
}

/** 逐出口明细的值域校验：陌生状态与读不出的理由都不该透传到设置页（那里直接渲染它们）。 */
function normalizeDelivery(value: unknown): ChannelDelivery | undefined {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return undefined;
  const source = value as Record<string, unknown>;
  if (typeof source.channelId !== "string") return undefined;
  if (source.status !== "ok" && source.status !== "failed" && source.status !== "skipped") {
    return undefined;
  }
  const delivery: ChannelDelivery = { channelId: source.channelId, status: source.status };
  const reason = normalizeReason(source.reason);
  if (reason !== undefined) delivery.reason = reason;
  const warning = warningOf(source);
  if (warning !== undefined) delivery.soundWarning = warning;
  return delivery;
}

/**
 * ok 随行警告的窄投影：坏的可选警告只丢该字段，主记录（状态与主理由）不受影响。
 * 有界：上限走 normalizeSoundWarning 缺省（与既有 300 同值）；旧主 reason 的开放语义不改。
 */
function warningOf(source: Record<string, unknown>): ChannelDelivery["soundWarning"] {
  if (source.status !== "ok") return undefined;
  return normalizeSoundWarning(source.soundWarning);
}

/** 本域唯一的存储实例：类不外放，外面 `new` 不出第二份写队列。 */
export const historyStore = new HistoryStore();

/**
 * dsh-notifier stores 域 —— 频道投递状态落盘实现：内存镜像 + debounce 合并的整文件原子写。
 *
 * 与历史同源但多一层 debounce：通知风暴时避免每条通知一次整文件重写。
 */
import {
  readTextFileSync,
  writeTextAtomic,
  STATUS_FILE_NAME,
  clampReasonDetail,
  normalizeReason,
  normalizeSoundWarning,
  notifierFile,
} from "../../../shared/interface.ts";
import type { ProducedReason } from "../../../shared/interface.ts";
import type { ChannelStatusEntry, StatusDeps } from "./type.ts";

/** 未装配时的占位：装配是必经路径，占位只是让字段不必每个使用点判空。 */
const UNINSTALLED: StatusDeps = { logger: { warn: () => {} } };

/** 状态条目上限（防已删频道残留键无限累积；超出时最旧先出）。 */
const STATUS_MAX_ENTRIES = 64;

/** 落盘 debounce 窗口（毫秒）：窗口内的多次 record 合并为一次整文件写。 */
const STATUS_DEBOUNCE_MS = 500;

/** 宿主原文（`detail`）上限（字符）：摘要会随 GET /status 出到设置页，够定位问题即可。
 * `code` / `params` 不受这条上限约束——它们是固定短标识，没有撑爆页面的风险。 */
const STATUS_ERROR_LIMIT = 300;
/** 待落盘状态：有改动尚未落盘时才持有定时器。 */
type PendingFlush = { pending: false } | { pending: true; timer: ReturnType<typeof setTimeout> };

/** 频道投递终态：内存镜像即时更新，落盘延后合并。 */
class StatusStore {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 落盘路径：DSH home 由环境决定、进程内不变，故随实例一次性定下。 */
  private readonly file = notifierFile(STATUS_FILE_NAME);
  private deps: StatusDeps = UNINSTALLED;
  /** 内存镜像：本类的单一事实源，冷启动从文件加载；空表即「尚未加载」。 */
  private mirror: Record<string, ChannelStatusEntry> = {};
  /** 落盘 debounce：窗口内多次 record 合并为一次整文件写。 */
  private flush: PendingFlush = { pending: false };
  /** 写队列串行化：整文件重写若并发交错，后写的会把先写的整份内容覆盖掉。 */
  private queue: Promise<void> = Promise.resolve();

  install(deps: StatusDeps): void {
    if (this.installed) throw new Error("dsh-notifier: 投递状态只能装配一次");
    this.installed = true;
    this.deps = deps;
  }

  /** 卸载：放开装配入参并丢掉内存镜像。镜像要一起丢——它是「磁盘状态」的记忆。 */
  release(): void {
    this.clearPendingFlush();
    this.installed = false;
    this.deps = UNINSTALLED;
    this.mirror = {};
  }

  /** 记录一次投递终态：内存立即更新，落盘延后合并（失败仅经日志出口告警）。 */
  record(
    channelId: string,
    status: "ok" | "failed",
    error?: ProducedReason,
    soundWarning?: ProducedReason,
  ): void {
    this.loadFromDisk();
    const prev = this.mirror[channelId];
    const entry: ChannelStatusEntry = {
      lastTs: Date.now(),
      lastStatus: status,
      // 连续失败计数跨重启延续：冷启动已把文件读进镜像，「上一次」因此就在 prev 里。
      failStreak: status === "ok" ? 0 : (prev === undefined ? 0 : prev.failStreak) + 1,
    };
    if (status === "failed" && error !== undefined) {
      entry.lastError = clampReasonDetail(error, STATUS_ERROR_LIMIT);
    }
    // 成功才可能带声音警告：失败不挂旧警告，下一次正常（无警告）清掉旧警告。
    if (status === "ok" && soundWarning !== undefined) {
      entry.lastSoundWarning = clampReasonDetail(soundWarning, STATUS_ERROR_LIMIT);
    }
    // 删了再插 = 移到表尾：镜像键序即最近使用序。频道 id 形如 `bark:<id>` 或内置通道名，
    // 不是整数样键——整数样键在对象里恒按数值升序枚举，回插改不动位置。
    delete this.mirror[channelId];
    this.mirror[channelId] = entry;
    this.evictOldest();
    this.scheduleFlush();
  }

  /** 读取全部频道状态（内存镜像优先，冷启动回落文件）。 */
  async read(): Promise<Record<string, ChannelStatusEntry>> {
    this.loadFromDisk();
    // 浅拷贝：镜像会被下一次 record 改写，调用方拿到的必须是「读到的那一刻」。
    return { ...this.mirror };
  }

  /**
   * 冷启动懒加载：把文件读进镜像。
   *
   * 必须同步读：`record` 是 fire-and-forget，异步加载会与它抢跑，让磁盘上的旧值把刚记下的
   * 投递盖回去。空表即「尚未加载」，读不出内容时下一次再读一遍。
   */
  private loadFromDisk(): void {
    if (Object.keys(this.mirror).length > 0) return;
    const read = readTextFileSync(this.file);
    if (!read.ok) return;
    try {
      const stored = JSON.parse(read.text) as Record<string, unknown>;
      for (const [channelId, entry] of Object.entries(stored)) {
        const normalized = normalizeEntry(entry);
        if (normalized !== undefined) this.mirror[channelId] = normalized;
      }
    } catch {
      // 半截 JSON：从空表开始，下一次落盘会用完整内容覆盖它。
    }
  }

  private scheduleFlush(): void {
    if (this.flush.pending) return;
    const timer = setTimeout(() => {
      this.flush = { pending: false };
      this.flushToDisk();
    }, STATUS_DEBOUNCE_MS);
    // 不把进程钉在事件循环上：丢掉的是「最近一次投递」的记录，下一次投递会重新记。
    timer.unref();
    this.flush = { pending: true, timer };
  }

  /** 丢掉待写定时器：卸载后这次落盘已没有要表达的事实。 */
  private clearPendingFlush(): void {
    if (this.flush.pending) clearTimeout(this.flush.timer);
    this.flush = { pending: false };
  }

  private flushToDisk(): void {
    // 快照先取：任务真正执行时镜像可能已被 release 丢掉，那时序列化出来的是一张空
    // 表——这次写本来要表达一次投递终态，却会把状态文件整份清掉。
    const snapshot = JSON.stringify(this.mirror, null, 2);
    const deps = this.deps;
    this.queue = this.queue.then(async () => {
      const written = await writeTextAtomic(this.file, snapshot);
      if (!written.ok) {
        deps.logger.warn(`dsh-notifier: 投递状态写入失败: ${written.reason}`);
      }
    });
  }

  private evictOldest(): void {
    const ids = Object.keys(this.mirror);
    const excess = ids.length - STATUS_MAX_ENTRIES;
    for (const channelId of ids.slice(0, Math.max(0, excess))) {
      delete this.mirror[channelId];
    }
  }
}

/**
 * 磁盘内容不受契约约束：只收「看起来是状态条目」的项，其余（陌生形态、半截值）丢掉。
 *
 * 值域也要校验，不能只看字段类型：`lastStatus` 是客户端直接画红绿的判据，把不认识的值透传出去
 * 之后，旧客户端会把任何 ≠ `"ok"` 的值渲染成「最近投递失败 + 红点」——一次降级就凭空多出一条
 * 故障。`lastError` 的旧形态（升级前写下的散文）在这里收编成结构化理由，读面因此不必再判两态。
 */
function normalizeEntry(entry: unknown): ChannelStatusEntry | undefined {
  if (typeof entry !== "object" || entry === null || Array.isArray(entry)) return undefined;
  const source = entry as Record<string, unknown>;
  if (typeof source.lastTs !== "number") return undefined;
  if (source.lastStatus !== "ok" && source.lastStatus !== "failed") return undefined;
  const normalized: ChannelStatusEntry = {
    lastTs: source.lastTs,
    lastStatus: source.lastStatus,
    // 计数缺失（早于本字段的形态）按 0 起算：它只用于展示连续失败次数，不是判据。
    failStreak: typeof source.failStreak === "number" ? source.failStreak : 0,
  };
  const lastError = normalizeReason(source.lastError);
  if (lastError !== undefined) normalized.lastError = lastError;
  const warning = warningOf(source, normalized.lastStatus);
  if (warning !== undefined) normalized.lastSoundWarning = warning;
  return normalized;
}

/**
 * 成功支随行警告的窄投影：坏的可选警告只丢该字段，主状态（终态与计数）不受影响；
 * 失败支上的警告不收。有界与主 reason 开放语义并存：警告 detail 按本文件既有上限截断，
 * 主 reason 不动。
 */
function warningOf(
  source: Record<string, unknown>,
  lastStatus: "ok" | "failed",
): ChannelStatusEntry["lastSoundWarning"] {
  if (lastStatus !== "ok") return undefined;
  return normalizeSoundWarning(source.lastSoundWarning, STATUS_ERROR_LIMIT);
}

/** 本域唯一的存储实例：类不外放，外面 `new` 不出第二份内存镜像。 */
export const statusStore = new StatusStore();

packages/dsh-notifier/test/integration/r.source:
/**
 * dsh-notifier — 组合根（`src/index.ts`）的真实 cordis Context 集成测试。
 *
 * 面口径：这里测的是**宿主看见的那一面**——`apply` 收窄宿主上下文、按序装配八个域、卸载逆序释放；
 * 「按序」里唯一在运行期无观测量的那一段（升级链 await 跑完才轮到读文件的域）以源码文本先后锁定。
 * 这些行为只有放进真实 cordis 才成立：`inject` 门（未就绪不装配）、两条 waterfall 的 `prepend`
 * 链序、`{ global: true }` 的作用域过滤、`ctx.effect` 的卸载时机、`internal/service` 的晚到通知。
 * 假宿主只提供 `webServer`（组合根唯一触碰的宿主服务）与可选的 `settings`；事件总线、落盘、
 * 裁决管线全是真的——**不 mock `@deepseek-ai/cordis`**，也不用 `vi.mock`/`vi.fn`。
 *
 * 落盘隔离（红线）：config / stores / stream 的单例在**模块加载期**就用 `notifierFile()` 定死了
 * 路径，所以必须先把 `DSH_HOME` 指到 `mkdtempSync` 出的临时目录，再用**动态 `import()`** 拉组合根。
 * 写反了本节全部落盘就进真实 `~/.dsh`——那正是正在跑的 `dsh web` 的 home。
 *
 * 写队列纪律：历史与配置的落盘是 fire-and-forget（写队列是模块级字段，`release` 不清它），故每个
 * 产生落盘的用例都要等到自己那一条在磁盘上可见才算完；需要「没有新写入」这类否定判据时，用
 * `stores` 域自己的写口排一次队当**界碑**——队列串行，界碑落盘即此前排队的全部落盘。
 *
 * 时间纪律：本文件不钉系统时钟，`pollUntil` 的 deadline 读的正是 `Date.now()`，钉住它失败会从
 * 「断言红」退化成挂死。`afterEach` 仍还原一次，防将来有人在用例里钉。
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import type { IncomingMessage } from "node:http";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { Context } from "@deepseek-ai/cordis";
import type { Events, Fiber, ThisType as EventThis } from "@deepseek-ai/cordis";
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import type { Session, SessionEvent } from "@deepseek-ai/dsh-session";
import type { ApprovalOutcome, ApprovalRequest } from "@deepseek-ai/dsh-user-approval";
import type {
  AskUserQuestionAnswer,
  AskUserQuestionRequest,
} from "@deepseek-ai/dsh-user-questions";

import {
  assertEventReachability,
  assertRealCordisContextSemantics,
} from "../../../../test/smoke-lib.ts";
import { DEFAULT_CONFIG } from "../../src/server/config/impl/model/index.ts";
import { jsonReq, makeRes, pollUntil, settleMicrotasks, tempDshHome } from "../helpers.ts";

// DSH_HOME 必须先于被测模块求值：三个单例的落盘路径在构造时定下，而静态 import 会在任何语句
// 之前执行——顺序反了，本节全部落盘就写进真实 `~/.dsh`。
const home = tempDshHome();
const notifier = await import("../../src/index.ts");
const apiApi = await import("../../src/server/api/interface.ts");
const configApi = await import("../../src/server/config/interface.ts");
const sdkApi = await import("../../src/server/sdk/interface.ts");
const storesApi = await import("../../src/server/stores/interface.ts");
const sharedApi = await import("../../src/server/shared/interface.ts");

/** 本插件的落盘位置（新布局：包私有目录，见 `shared/paths.ts`）。 */
const storageDir = join(home.dir, "@wingsky-1", "dsh-notifier");
const configFile = sharedApi.notifierFile(sharedApi.CONFIG_FILE_NAME);
const historyFile = sharedApi.notifierFile(sharedApi.HISTORY_FILE_NAME);
const seqFile = sharedApi.notifierFile(sharedApi.SEQ_FILE_NAME);
const versionFile = sharedApi.notifierFile(sharedApi.VERSION_FILE_NAME);

/** 种下的那份配置的原文：否定判据用它比对「一个字节都没动过」。 */
function seededConfig(): string {
  return `${JSON.stringify(BASE_SETTINGS, null, 2)}\n`;
}

/** 宿主契约冻结的 8 条浏览器端点（客户端锁定，独立抄写才守得住改路径）。 */
const ROUTE_PATHS: readonly string[] = [
  "/api/dsh-notifier/config",
  "/api/dsh-notifier/history",
  "/api/dsh-notifier/status",
  "/api/dsh-notifier/kinds",
  "/api/dsh-notifier/test",
  "/api/dsh-notifier/health",
  "/api/dsh-notifier/diagnostics",
  "/api/dsh-notifier/events",
];

/**
 * 基础设置：系统出口整个关掉、浏览器出口只弹不响。
 *
 * 系统出口在 Linux 会真的 spawn `notify-send`——测试不该在开发机上弹通知；浏览器出口的帧则
 * 经组合根的 `FrameBus` 进 api 域的流（只写 `seq.json`），是本文件观察「帧走出去了」的唯一手段。
 * 两条内置频道的形态**显式写出来**：`enabled` 是频道唯一的投递闸门，靠 `systemNotify:false`
 * 之类的弹窗键关不掉它（那只让出口无事可做，仍会留下一条 skipped 明细）。
 * `historyMaxAgeDays` 取**非默认值**：逆序释放那条判据要一个与默认值不同的可辨读数。
 */
const BASE_SETTINGS = {
  channels: [
    {
      type: "browser",
      id: "browser",
      enabled: true,
      popup: true,
      sound: false,
      whenVisible: false,
    },
    { type: "system", id: "system", enabled: false, popup: false, sound: false },
  ],
  historyMaxAgeDays: 7,
} as const;

/** 历史行：只取本文件当判据的字段（整体比较会把域内文案变化变成假红）。 */
interface HistoryLine {
  kind?: string;
  title?: string;
  message?: string;
  suppressed?: string;
  channels?: ReadonlyArray<{ channelId: string; status: string }>;
}

/** 磁盘上的历史记录。 */
function historyLines(): HistoryLine[] {
  let text: string;
  try {
    text = readFileSync(historyFile, "utf8");
  } catch {
    return [];
  }
  return text
    .split("\n")
    .filter(Boolean)
    .flatMap((line) => {
      try {
        return [JSON.parse(line) as HistoryLine];
      } catch {
        // 坏行不当判据，也不吞掉同行之外的记录
        return [];
      }
    });
}

/** 某一种通知落了几条。 */
function countKind(kind: string): number {
  return historyLines().filter((line) => line.kind === kind).length;
}

/** 磁盘上第一条某一种通知：`beforeEach` 清过历史，所以不受上一个用例干扰。 */
function kindLine(kind: string): HistoryLine | undefined {
  return historyLines().find((line) => line.kind === kind);
}

/** 同一 kind 的第 N 条记录：动态 locale 用例要在同一次装配里比较前后两份文案。 */
function kindLines(kind: string): HistoryLine[] {
  return historyLines().filter((line) => line.kind === kind);
}

/** 界碑用的种类名：只出现在界碑行里，任何通知判据都不会撞上它。 */
const SENTINEL_KIND = "itest-sentinel";

/**
 * 排一次界碑并等它落盘，用来给**否定**判据划界。
 *
 * 写队列串行，界碑在磁盘上可见即此前排队的写入全部落盘；没有界碑的「没有新记录」只是抢跑得来的
 * ——它证明的是「还没写完」，不是「不会写」。
 */
async function settleHistory(): Promise<void> {
  storesApi.appendHistory({ ts: Date.now(), kind: SENTINEL_KIND, title: "界碑", message: "-" });
  await pollUntil(() => historyLines().some((line) => line.kind === SENTINEL_KIND), "界碑落盘");
}

/** 浏览器出口的序号：`seq.json` 前进一格 = 帧真的走完了 FrameBus → api 域 → 流。 */
function seqValue(): number {
  try {
    const parsed = Number.parseInt(readFileSync(seqFile, "utf8").trim(), 10);
    return Number.isFinite(parsed) ? parsed : 0;
  } catch {
    return 0;
  }
}

/**
 * 本用例的序号锚点（每轮 +1000）。
 *
 * 序号是 fire-and-forget 写，「等于锚点 +1」这类判据要挡得住上一个用例迟到的那一笔——递增的锚点
 * 让迟到的值必然小于本轮的起点，于是「文件里出现了本轮的格子」只可能由本轮自己的广播产生。
 */
let seqAnchor = 0;

function seedSeqAnchor(): void {
  seqAnchor += 1000;
  mkdirSync(dirname(seqFile), { recursive: true });
  writeFileSync(seqFile, `${seqAnchor}\n`);
}

/** 写一份设置文件（组合根装配时同步读它，故必须用同步写）。 */
function seed(settings: Record<string, unknown>): void {
  mkdirSync(dirname(configFile), { recursive: true });
  writeFileSync(configFile, `${JSON.stringify(settings, null, 2)}\n`);
}

/** 假会话日志条目：本块只读 `type` 与 `data`（与 events 域单测同一口径）。 */
function turnEndEvent(turn: number, kind: string): SessionEvent {
  return { type: "turn/end", data: { turn, reason: { kind } } } as unknown as SessionEvent;
}

/** 假 agent：只露出 events 域真的会读的几处（`id` 与 `session` 的 header / 日志快照）。 */
function fakeAgent(
  id: string,
  events: SessionEvent[] = [],
  header: Record<string, unknown> = {},
): Agent {
  return {
    id,
    session: { header, snapshotEvents: () => events },
  } as unknown as Agent;
}

/** 假会话：`session/event` 的载荷带整份会话对象，而本插件只用它的 `id`。 */
function fakeSession(id: string): Session {
  return { id } as unknown as Session;
}

/**
 * 宿主按作用域派发时传的 `this`：`agent/*` 声明的是 `Scoped<Agent>`、`session/event` 是
 * `Scoped<Session>`，而那个 brand 不是本包的依赖，故从事件签名上取 `this` 位。测试要造的正是
 * `{ [Context.filter]: … }` 这一个成员——直接抄 `Scoped<…>` 会把它变成第二份事实源。
 */
type ScopedThis<K extends keyof Events> = EventThis<Events[K]>;

/** 作用域收紧的派发载体：filter 恒假，于是**只有** `{ global: true }` 的订阅能收到。 */
function scopeRejecting<K extends keyof Events>(): ScopedThis<K> {
  return { [Context.filter]: () => false } as unknown as ScopedThis<K>;
}

/**
 * 假 settings 服务只提供 describe 低优先级兜底；正式历史来源由 upgrade 域直接读取 DSH_HOME 双文件。
 * `describe()` 在真实宿主里只列**已注册**的命名空间，所以这里的 `user` 用三种取值对应三种真实形态：
 * `undefined` = 没注册这条命名空间（新架构的常态，服务面读不到）；`{}` = 注册了但 user 层为空；有键 = 注册且用户设过。
 */
function fakeSettings(
  user: Record<string, unknown> | undefined,
  locale?: () => { readonly value?: unknown },
): { describe: () => unknown[] } {
  return {
    describe: () => {
      const entries = user === undefined ? [] : [{ ns: "dsh-notifier", value: user, user }];
      if (locale === undefined) return entries;
      return [
        ...entries,
        {
          ns: "locale",
          value: locale().value,
          user: { preference: "zh" },
        },
      ];
    },
  };
}

/**
 * 假宿主 webServer：只实现组合根够得着的那一面（`register`），并记下摘除时的现场。
 *
 * `failAt` 让第 N 条摘除器抛错——宿主摘路由失败是真实会发生的（路由已被别人摘掉、宿主换实现），
 * 组合根的释放壳对它的承诺是「不阻断其余」。
 */
function fakeWebServer(
  observe: () => { configDays: number; serviceAlive: boolean },
  options: { failAt?: number } = {},
) {
  const routes: WebRoute[] = [];
  const removals: Array<{ path: string; configDays: number; serviceAlive: boolean }> = [];
  const service = {
    register(route: WebRoute) {
      routes.push(route);
      return () => {
        removals.push({ path: route.path, ...observe() });
        if (removals.length === options.failAt) throw new Error(`摘除失败：${route.path}`);
      };
    },
  } as unknown as Context["webServer"];
  return { service, routes, removals };
}

/** 假宿主 agent 注册表：只实现组合根读的两处（`get` 与 `isOwnedBy`）。 */
function fakeAgents(parent: Agent, child: Agent): Context["agents"] {
  return {
    get: (id: string) => (id === parent.id ? parent : undefined),
    isOwnedBy: (id: string, owner: Agent) => id === child.id && owner === parent,
  } as unknown as Context["agents"];
}

/**
 * 日志出口：`LoggerService` 的公开扩展点，用它把 warn 收进数组。
 *
 * 为什么不读内置的 `ctx.logger.buffer`：那个出口的阈值是 INFO，warn（级别 2）落在它之外，
 * buffer 里永远看不到本文件的判据文案。阈值按 `levels.default` 给——它是出口自己的约定。
 */
function captureWarnings(root: Context): string[] {
  const warnings: string[] = [];
  root.logger.exporter({
    levels: { default: 2 },
    export: (message) => {
      if (message.type === "warn") warnings.push(String(message.args[0]));
    },
  });
  return warnings;
}

/** 一次挂载的全部观测物。 */
interface Mounted {
  readonly root: Context;
  readonly fiber: Fiber;
  readonly host: ReturnType<typeof fakeWebServer>;
  /** 宿主日志出口收到的 warn 文案（组合根只经它报错）。 */
  readonly warns: string[];
  unmount(): Promise<void>;
}

/** 已挂载但用例没显式卸载的实例：`afterEach` 兜底收掉，免得路由/心跳漏到下一个用例。 */
let live: Fiber | null = null;

/**
 * 按宿主的真实挂载顺序装配：先 provide 宿主服务，再 `ctx.plugin(插件)`。
 *
 * `settings` 是本插件的**显式依赖**（组合根的 `inject`）：宿主保证它在插件装配前就绪，所以这里
 * 总是先 provide 一个假的；`settings` 的值就是那份 0.2.3 存量命名空间的 user 层（缺省 = 有服务
 * 但没存量）。「服务没来」这条分支已不属于本插件——它变成 cordis 的 inject 门（见 inject 门用例）。
 * `services` 是其余宿主服务（如 `agents`）——装与不装是两条不同的判定路径。
 */
async function mount(options: {
  config?: { enabled?: boolean };
  settings?: Record<string, unknown>;
  locale?: () => { readonly value?: unknown };
  services?: Record<string, unknown>;
}): Promise<Mounted> {
  const root = new Context();
  root.provide("settings", fakeSettings(options.settings, options.locale));
  for (const [name, value] of Object.entries(options.services ?? {})) root.provide(name, value);
  const warns = captureWarnings(root);
  const host = fakeWebServer(() => ({
    configDays: configApi.readConfig().historyMaxAgeDays,
    serviceAlive: root.get("wingsky.notifier", false) !== undefined,
  }));
  root.provide("webServer", host.service);
  const fiber = await root.plugin(notifier, options.config);
  live = fiber;
  return {
    root,
    fiber,
    host,
    warns,
    unmount: async () => {
      live = null;
      await fiber.dispose();
    },
  };
}

/** 走组合根实际注册的路由，验证测试按钮端点也使用按请求现读的 locale。 */
async function postTestNotification(routes: readonly WebRoute[]): Promise<void> {
  const path = "/api/dsh-notifier/test";
  const route = routes.find((item) => item.path === path);
  if (route === undefined) throw new Error(`路由未注册: ${path}`);
  const request = jsonReq({ method: "POST", url: path, body: {} }) as IncomingMessage;
  const captured = makeRes();
  route.handler(request, captured.res);
  await pollUntil(() => captured.rec.headersSent, `${path} 未写出响应`);
  expect(captured.rec.status).toBe(200);
}

/**
 * 模拟宿主内置 answerer：链上**更早注册**的那一个，它给出的判定就是这次请求的最终结果。
 * 它不调 `next()`——宿主自己的应答者拿到判定后即短路，这正是本插件必须 prepend 的理由。
 */
async function mountApprovalAnswerer(
  root: Context,
  calls: string[],
  outcome: ApprovalOutcome,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("approval/request", () => {
      calls.push("answerer");
      return Promise.resolve(outcome);
    });
  });
}

/** 同上，提问那条链上的 answerer（两条 waterfall 同构，夹具分开写以免一条覆盖另一条）。 */
async function mountQuestionAnswerer(
  root: Context,
  calls: string[],
  answer: AskUserQuestionAnswer,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("user-questions/request", () => {
      calls.push("answerer");
      return Promise.resolve(answer);
    });
  });
}

beforeEach(() => {
  // 单例的落盘路径跨用例不变，能重置的只有文件：不重置的话上一个用例的配置/历史就是本用例的起点。
  rmSync(historyFile, { force: true });
  rmSync(configFile, { force: true });
  // 正式历史来源也落在这个共享的临时 DSH_HOME 里；清掉双文件，避免上个用例的存量进入下个用例。
  rmSync(join(home.dir, "settings.yaml.imported"), { force: true });
  rmSync(join(home.dir, "settings.yaml"), { force: true });
  seedSeqAnchor();
  seed(BASE_SETTINGS);
});

afterEach(async () => {
  vi.useRealTimers();
  if (live) {
    const fiber = live;
    live = null;
    await fiber.dispose();
  }
  // 无条件补一次 api 域收尾：域释放幂等，正常用例上是空转。不放在用例里是因为用例前面任何一条
  // 断言红了就会跳过补偿（路由/心跳会漏到下一个用例，症状是「上一条用例弄脏了这条」）。
  apiApi.releaseApi();
});

afterAll(() => {
  home.dispose();
});

describe("装配与暴露", () => {
  it("装配即暴露：服务面挂在宿主上下文上（声明合并的读法可用），登记与发送当场可用", async () => {
    const { root, fiber, unmount } = await mount({});
    // 声明合并的读法可用，而且读到的是**同一个**对象：服务面经 `ctx.provide` 挂在宿主上下文上，
    // 不是又造了一份（再造一份就会有两个 apiVersion、两套登记表）。
    const service = root.get("wingsky.notifier", false);
    expect(fiber.ctx["wingsky.notifier"]).toBe(service);
    expect(service?.apiVersion).toBe(2);
    // 管理面（清单 / 确认）不进服务面：多给一样，兄弟插件就能替用户放行自己的通知种类。
    expect("confirmKind" in (service ?? {})).toBe(false);

    service?.registerKind({ id: "itest:face", label: "集成测试" });
    expect(sdkApi.listKinds()).toContainEqual({
      id: "itest:face",
      label: "集成测试",
      confirmed: false,
    });
    // 未确认的外部种类：送进的是真管线，出去的是一条「unlisted」归档（不是静默丢弃）。
    await service?.send({ kind: "itest:face", body: "正文" });
    await pollUntil(() => countKind("itest:face") === 1, "登记后的发送落史");
    expect(kindLine("itest:face")?.suppressed).toBe("unlisted");

    await unmount();
    // 卸载后消费方按「通知中心不在」降级：`get` 拿空而不是拿到半死对象。
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
  });

  it("宿主 locale 实时接线：显式 en 覆盖 user 层、同次装配切回 zh、生成后历史不重写", async () => {
    let preference: unknown = "en";
    const { root, host, unmount } = await mount({
      locale: () => ({ value: { preference } }),
    });

    root.emit("agent/error", {
      agent: fakeAgent("itest-locale-en"),
      turn: 1,
      step: 1,
      error: new Error("failed"),
    });
    await pollUntil(() => countKind("error") === 1, "英文错误通知落史");
    const englishError = kindLines("error")[0];
    expect(englishError).toMatchObject({
      title: "DSH: Task failed",
      message: "Task failed\nTurn 1, step 1: failed",
    });

    await postTestNotification(host.routes);
    await pollUntil(() => countKind("test") === 1, "英文测试通知落史");
